mod tests_create_user_api {
    use super::*;

    // Test 1: API Boundary Contract - Verify signature and return type
    #[tokio::test]
    #[ignore = "RED PHASE: Scaffold test - fails until feature complete"
    async fn test_create_user_signature_is_public_async() {
        // ATDD Red Phase: This test verifies the API contract
        // Expected: pub async fn(name: String) -> Result<u64, String>
        // Will fail until implementation matches contract

        let result = create_user("alice".to_string()).await;

        // Expect Success variant
        assert!(result.is_ok(), "create_user should return Ok variant");

        // Expect u64 user ID in success case
        let user_id = result.expect("should have user ID");
        assert!(user_id > 0, "user ID should be positive integer");
    }

    // Test 2: Happy Path - Valid input succeeds
    #[tokio::test]
    #[ignore = "RED PHASE: Scaffold test - fails until feature complete"
    async fn test_create_user_happy_path_valid_name() {
        // ATDD Red Phase: Happy path validation
        // Expected: Valid name input returns Ok(user_id)

        let result = create_user("bob".to_string()).await;

        assert!(result.is_ok(), "valid name should succeed");
        let user_id = result.unwrap();
        assert_ne!(user_id, 0, "should return non-zero user ID");
    }

    // Test 3: Validation Failure - Empty name
    #[tokio::test]
    #[ignore = "RED PHASE: Scaffold test - fails until feature complete"
    async fn test_create_user_validation_empty_name() {
        // ATDD Red Phase: Validation edge case
        // Expected: Empty name returns Err(String) with validation message

        let result = create_user(String::new()).await;

        assert!(result.is_err(), "empty name should fail validation");
        let error = result.unwrap_err();
        assert!(!error.is_empty(), "error message should be descriptive");
    }

    // Test 4: Validation Failure - Name too long
    #[tokio::test]
    #[ignore = "RED PHASE: Scaffold test - fails until feature complete"
    async fn test_create_user_validation_name_too_long() {
        // ATDD Red Phase: Boundary validation
        // Expected: Extremely long name returns Err(String)
        // Core-001: Contract specifies acceptable input bounds

        let long_name = "a".repeat(10000);
        let result = create_user(long_name).await;

        assert!(result.is_err(), "excessively long name should fail");
    }

    // Test 5: Error Propagation - Join errors handled
    #[tokio::test]
    #[ignore = "RED PHASE: Scaffold test - fails until feature complete"
    async fn test_create_user_handles_spawn_errors() {
        // ATDD Red Phase: Async boundary error handling
        // Core-009: Task ownership and cleanup must be explicit
        // Expected: JoinError from spawned task is converted to Result<_, String>

        let result = create_user("charlie".to_string()).await;

        // If spawn/join fails, should get Err, not panic
        // Test will fail if unhandled panic or non-Result<_, String> type
        match result {
            Ok(id) => assert!(id > 0),
            Err(e) => assert!(!e.is_empty()),
        }
    }

    // Test 6: Cancellation Semantics - Task can be cancelled
    #[tokio::test]
    #[ignore = "RED PHASE: Scaffold test - fails until feature complete"
    async fn test_create_user_cancellation_on_drop() {
        // ATDD Red Phase: Explicit cancellation semantics
        // Core-009: Spawned task must have explicit lifecycle
        // RP-ASYNC-006: Task ownership and cancellation explicit
